import { test, expect } from '@playwright/test';

test.describe('Public Profile Page', () => {
  const baseUrl = 'http://localhost:3000';
  const profileUrl = `${baseUrl}/profile/public`;
  const testUsername = 'testuser123';
  const testEmail = 'testuser@example.com';
  const testBio = 'This is my public bio';
  const testLocation = 'San Francisco, CA';

  test.beforeEach(async ({ page }) => {
    await page.goto(profileUrl);
  });

  test('should display public profile page with user information', async ({ page }) => {
    // Verify page title and heading
    await expect(page).toHaveTitle(/Public Profile/i);

    const profileHeading = page.getByRole('heading', { name: /public profile/i });
    await expect(profileHeading).toBeVisible();

    // Verify username is displayed
    const usernameElement = page.getByText(testUsername);
    await expect(usernameElement).toBeVisible();

    // Verify email is displayed
    const emailElement = page.getByText(testEmail);
    await expect(emailElement).toBeVisible();

    // Verify bio section exists and contains expected text
    const bioSection = page.getByRole('region', { name: /bio/i });
    await expect(bioSection).toBeVisible();
    await expect(bioSection).toContainText(testBio);

    // Verify location is displayed
    const locationElement = page.getByText(testLocation);
    await expect(locationElement).toBeVisible();
  });

  test('should display profile picture and user details in correct layout', async ({ page }) => {
    // Verify profile picture is visible
    const profileImage = page.getByRole('img', { name: /profile picture/i });
    await expect(profileImage).toBeVisible();

    // Verify profile image has proper attributes
    await expect(profileImage).toHaveAttribute('alt', /profile picture/i);

    // Verify user details section exists
    const detailsSection = page.getByRole('region', { name: /user details/i });
    await expect(detailsSection).toBeVisible();

    // Verify all required fields are present in the details section
    const nameField = page.getByLabel(/full name/i);
    await expect(nameField).toBeVisible();

    const emailField = page.getByLabel(/email/i);
    await expect(emailField).toBeVisible();

    const locationField = page.getByLabel(/location/i);
    await expect(locationField).toBeVisible();
  });

  test('should display social links and follow button', async ({ page }) => {
    // Verify social links section exists
    const socialLinksSection = page.getByRole('region', { name: /social links/i });
    await expect(socialLinksSection).toBeVisible();

    // Verify follow button is present and clickable
    const followButton = page.getByRole('button', { name: /follow/i });
    await expect(followButton).toBeVisible();
    await expect(followButton).toBeEnabled();

    // Verify social media links are displayed
    const twitterLink = page.getByRole('link', { name: /twitter/i });
    const linkedinLink = page.getByRole('link', { name: /linkedin/i });

    if (await twitterLink.isVisible()) {
      await expect(twitterLink).toHaveAttribute('href', /twitter/i);
    }

    if (await linkedinLink.isVisible()) {
      await expect(linkedinLink).toHaveAttribute('href', /linkedin/i);
    }
  });

  test('should display user statistics and activity information', async ({ page }) => {
    // Verify statistics section exists
    const statsSection = page.getByRole('region', { name: /statistics/i });
    await expect(statsSection).toBeVisible();

    // Verify follower count is displayed
    const followerCount = page.getByText(/followers/i);
    await expect(followerCount).toBeVisible();

    // Verify following count is displayed
    const followingCount = page.getByText(/following/i);
    await expect(followingCount).toBeVisible();

    // Verify posts count is displayed
    const postsCount = page.getByText(/posts/i);
    await expect(postsCount).toBeVisible();

    // Verify member since date is displayed
    const memberSinceText = page.getByText(/member since/i);
    await expect(memberSinceText).toBeVisible();
  });

  test('should have proper accessibility attributes and semantic HTML', async ({ page }) => {
    // Verify main content area is properly marked
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Verify all headings follow proper hierarchy
    const headings = page.getByRole('heading');
    const headingCount = await headings.count();
    expect(headingCount).toBeGreaterThan(0);

    // Verify navigation links are present
    const navLinks = page.getByRole('navigation');
    await expect(navLinks).toBeVisible();

    // Verify back button or navigation link exists
    const backButton = page.getByRole('link', { name: /back|home/i });
    await expect(backButton).toBeVisible();
  });

  test('should handle missing optional profile fields gracefully', async ({ page }) => {
    // Check if optional fields are present but may be empty
    const bioSection = page.getByRole('region', { name: /bio/i });

    // If bio section exists, it should either have content or show placeholder
    if (await bioSection.isVisible()) {
      const bioContent = bioSection.getByText(/./);
      const bioEmpty = bioSection.getByText(/no bio|add bio/i);

      const hasContent = await bioContent.isVisible().catch(() => false);
      const isEmpty = await bioEmpty.isVisible().catch(() => false);

      expect(hasContent || isEmpty).toBeTruthy();
    }

    // Verify required fields are always present
    const usernameElement = page.getByText(testUsername);
    await expect(usernameElement).toBeVisible();
  });
});
